css:
.ovw-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.ovw-root,.ovw-root *,.ovw-root *::before,.ovw-root *::after{box-sizing:border-box}
.ovw-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.ovw-root img{display:block;border:0;max-width:none}
.ovw-root > [data-node-id]{will-change:transform}
.ovw-root [hidden]{display:none!important}
.ovw-root [data-sh-theme="light"]{display:none!important}
.ovw-root[data-theme="light"] [data-sh-theme="light"]{display:block!important}
.ovw-root[data-theme="light"] [data-sh-theme="dark"]{display:none!important}
.ovw-root .n22_1353{background-color:color-mix(in srgb, var(--wa-point, rgb(209 234 255)) 10%, transparent);align-content:stretch;display:flex;flex-direction:column;height:22px;align-items:center;justify-content:center;position:relative;flex-shrink:0;width:51px;border-style:solid;border-color:color-mix(in srgb, var(--wa-point, rgb(0 183 238)) 10%, transparent);border-width:0px}
.ovw-root .n22_1354{align-content:stretch;display:flex;gap:5px;align-items:center;position:relative;flex-shrink:0;height:12px}
.ovw-root .n22_1355{position:relative;flex-shrink:0;width:12px;height:12px}
.ovw-root .x87{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.ovw-root .n22_1356{text-box-edge:cap alphabetic;text-box-trim:trim-both;word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;line-height:normal;font-style:normal;position:relative;flex-shrink:0;font-size:12px;color:var(--wa-text, #fff);white-space:nowrap;width:14px;height:8px}
.ovw-root[data-theme="light"] [data-name="Badge/Gas Level"] p{color:var(--wa-text, #fff)!important}
.ovw-root[data-theme="light"] [data-name="Badge/Critical"] p,.ovw-root[data-theme="light"] [data-name^="status-critical"] p,.ovw-root[data-theme="light"] [data-name="Count/Critical"] p{color:var(--wa-danger, #ad152d)!important;font-weight:600;white-space:nowrap}
.ovw-root[data-theme="light"] [data-name="Badge/Major"] p,.ovw-root[data-theme="light"] [data-name^="status-major"] p,.ovw-root[data-theme="light"] [data-name="Count/Major"] p{color:var(--wa-warn, #8f3f00)!important;font-weight:600;white-space:nowrap}
.ovw-root[data-theme="light"] [data-name="Badge/Minor"] p,.ovw-root[data-theme="light"] [data-name^="status-minor"] p,.ovw-root[data-theme="light"] [data-name="Count/Minor"] p{color:var(--wa-warn, #6b4d00)!important;font-weight:600;white-space:nowrap}
.ovw-root[data-theme="light"] [data-name="Badge/Warning"] p,.ovw-root[data-theme="light"] [data-name^="status-warning"] p,.ovw-root[data-theme="light"] [data-name="Count/Warning"] p{color:var(--wa-point, #1356b3)!important;font-weight:600;white-space:nowrap}
.ovw-root[data-theme="light"] [data-name="Badge/Normal"] p,.ovw-root[data-theme="light"] [data-name^="status-normal"] p,.ovw-root[data-theme="light"] [data-name="Count/Normal"] p{color:var(--wa-text-sub, #4b5868)!important;font-weight:600;white-space:nowrap}
.ovw-root[data-theme="light"] [data-name="Button/Ack"] p,.ovw-root[data-theme="light"] [data-name="Button/Ack All"] p,.ovw-root[data-theme="light"] [data-name="Button/Reset"] p{color:var(--wa-text, #fff)!important}
.ovw-root [data-name="Header"] > [data-name="Bullet"]:has(> [data-name="Base"]){transform-origin:0 4px;transform:translate(4px,-4px) scaleY(0.8889)}
.ovw-root [data-name="Event Log"] [data-name="Toolbar"] [data-name="Bullet"] > [data-name]{translate:2px 0}
.ovw-root [data-name="Header"] > [data-name="Bullet"]:not(:has(> [data-name="Base"])){transform-origin:0 1.83px;transform:translate(2px,-4.17px) scaleY(0.8649)}
.ovw-root[data-theme="light"] [data-name="Nav"]{background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 60%, transparent)!important}
.ovw-root[data-theme="light"]{color:var(--wa-point, #15253a)}
.ovw-root[data-theme="light"] [data-name="Logo Group"] [data-name="Title"]{background-image:linear-gradient(to right,var(--wa-point, #1d4fc4),var(--wa-point, #3a7ee6))!important}
.ovw-root[data-theme="light"] [data-name="Clock"] [data-name="Time"]{background-image:linear-gradient(to top,var(--wa-point, #173f9e),var(--wa-point, #2e72dc) 86.843%)!important}
.ovw-root[data-theme="light"] :is([data-name="Symbol"],[data-name="Floor"],[data-name="Floor Layer"],[data-name="Effect"]) img{filter:brightness(1.75) saturate(.55);opacity:.7}
.ovw-root[data-theme="light"] :is([data-name="Button/Stop"],[data-name="Button/Own"],[data-name="Button/Ack"],[data-name="Button/Select"]) img{content:normal!important}
.ovw-root[data-theme="light"] :is([data-name="Button/Stop"],[data-name="Button/Own"],[data-name="Button/Ack"],[data-name="Button/Select"]) p{color:var(--wa-text, #fff)!important}
.ovw-root[data-theme="light"] [data-name="Button/Stop"]{background:var(--wa-point, #1e86f0)!important}
.ovw-root[data-theme="light"] [data-name="Button/Own"]{background:var(--wa-point, #2d6bd6)!important}
.ovw-root[data-theme="light"] [data-name="Button/Ack"]{background:var(--wa-point, #24489f)!important}
.ovw-root[data-theme="light"] [data-name="Button/Select"]{background:var(--wa-point, #1f6fd8)!important}
.ovw-root[data-theme="light"] :is([data-name^="Node/"],[data-name="Icons"],[data-name="Node Group"]) p{text-shadow:0 0 3px #fff,0 0 6px #fff,0 0 10px rgba(255,255,255,.9)}
.ovw-root[data-theme="light"] .n22_1356{color:var(--wa-point, #0f2238)}
